import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_activation_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ float softplus(float x) {
    return log1pf(expf(x));
}

__global__ void fused_activation_kernel(const float* input, float add_value, float scale, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx];

        // Mish activation: x * tanh(softplus(x))
        float sp = softplus(x);
        float mish = x * tanhf(sp);

        // Add value and apply Hardtanh
        float val = mish + add_value;
        val = fmaxf(fminf(val, 1.0f), -1.0f);

        // Scale output
        output[idx] = val * scale;
    }
}

torch::Tensor fused_activation_cuda(torch::Tensor input, float add_value, float scale) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();

    const int threads = 256;
    const int blocks = (num_elements + threads - 1) / threads;

    fused_activation_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        add_value,
        scale,
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

fused_activation_cpp = "torch::Tensor fused_activation_cuda(torch::Tensor input, float add_value, float scale);"

fused_activation = load_inline(
    name='fused_activation',
    cpp_sources=fused_activation_cpp,
    cuda_sources=fused_activation_source,
    functions=['fused_activation_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, add_value, scale):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, 
                                                stride, padding, output_padding)
        self.add_value = add_value
        self.scale = scale
        self.fused_activation = fused_activation

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_activation.fused_activation_cuda(x, self.add_value, self.scale)
        return x
